"""Recurring transactions: schedules in words and dated copies of a template."""

import datetime
import re

from tallybook.dates import DateError, add_months, last_day, parse_date
from tallybook.errors import ValidationError, is_int
from tallybook.model import Transaction

__all__ = ["Schedule", "Recurring", "RecurringError", "parse_schedule", "occurrences", "expand",
           "instantiate", "next_occurrence", "describe"]


class RecurringError(ValidationError):
    """A malformed schedule or recurring item."""


SHAPES = ("daily, weekly on DAY (mon..sun), monthly on N (1-31), monthly on last, yearly on MM-DD, "
          "every N days|weeks|months|years from YYYY-MM-DD")

_WEEKDAYS = ("mon", "tue", "wed", "thu", "fri", "sat", "sun")
_WEEKDAY_NAMES = ("Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday")
_MONTH_NAMES = ("January", "February", "March", "April", "May", "June", "July", "August", "September",
                "October", "November", "December")
_UNITS = {"day": "day", "days": "day", "week": "week", "weeks": "week",
          "month": "month", "months": "month", "year": "year", "years": "year"}
_NAME_RE = re.compile(r"[A-Za-z0-9][A-Za-z0-9_-]*")
_MIN_ORD = datetime.date.min.toordinal()
_MAX_ORD = datetime.date.max.toordinal()


def _is_date(value):
    return isinstance(value, datetime.date) and not isinstance(value, datetime.datetime)


def _ceil_div(a, b):
    return -((-a) // b)


class Schedule:
    """A rhythm of dates. Build one with parse_schedule.

    kind is one of daily, weekly (value: weekday 0-6), monthly (value: 1-31 or "last"),
    yearly (value: (month, day)), every (value: (n, unit, from_date)).
    """

    __slots__ = ("_kind", "_value")

    def __init__(self, kind, value=None):
        object.__setattr__(self, "_kind", kind)
        object.__setattr__(self, "_value", value)

    kind = property(lambda self: self._kind)
    value = property(lambda self: self._value)

    def __setattr__(self, name, value):
        raise AttributeError("Schedule is immutable")

    def __delattr__(self, name):
        raise AttributeError("Schedule is immutable")

    def __reduce__(self):
        return (parse_schedule, (str(self),))

    def __eq__(self, other):
        if not isinstance(other, Schedule):
            return NotImplemented
        return self._kind == other._kind and self._value == other._value

    def __ne__(self, other):
        r = self.__eq__(other)
        return r if r is NotImplemented else not r

    def __hash__(self):
        return hash((self._kind, self._value))

    def __str__(self):
        k, v = self._kind, self._value
        if k == "daily":
            return "daily"
        if k == "weekly":
            return "weekly on %s" % _WEEKDAYS[v]
        if k == "monthly":
            return "monthly on %s" % v
        if k == "yearly":
            return "yearly on %02d-%02d" % v
        n, unit, frm = v
        return "every %d %s from %s" % (n, unit if n == 1 else unit + "s", frm.isoformat())

    def __repr__(self):
        return "Schedule(%r)" % str(self)

    # ------------------------------------------------------------ index model
    # The schedule's dates are indexed by integers k, ascending in k. _date(k)
    # returns the k-th date or None when it is outside the date range;
    # _index_ge(d) returns the smallest index whose date is >= d.

    def _date(self, k):
        kd, v = self._kind, self._value
        try:
            if kd == "daily":
                if not _MIN_ORD <= k <= _MAX_ORD:
                    return None
                return datetime.date.fromordinal(k)
            if kd == "weekly":
                o = 7 * k + 1 + v
                if not _MIN_ORD <= o <= _MAX_ORD:
                    return None
                return datetime.date.fromordinal(o)
            if kd == "monthly":
                y, m = divmod(k, 12)
                m += 1
                if not 1 <= y <= 9999:
                    return None
                ld = last_day(y, m)
                return datetime.date(y, m, ld if v == "last" else min(v, ld))
            if kd == "yearly":
                if not 1 <= k <= 9999:
                    return None
                mo, dd = v
                return datetime.date(k, mo, min(dd, last_day(k, mo)))
            n, unit, frm = v
            if k < 0:
                return None
            if unit in ("day", "week"):
                o = frm.toordinal() + k * n * (7 if unit == "week" else 1)
                if o > _MAX_ORD:
                    return None
                return datetime.date.fromordinal(o)
            months = k * n * (12 if unit == "year" else 1)
            if frm.year * 12 + frm.month - 1 + months > 9999 * 12 + 11:
                return None
            return add_months(frm, months)
        except (OverflowError, ValueError, DateError):
            return None

    def _index_ge(self, d):
        kd, v = self._kind, self._value
        if kd == "daily":
            return d.toordinal()
        if kd == "weekly":
            return _ceil_div(d.toordinal() - 1 - v, 7)
        if kd == "monthly":
            k = d.year * 12 + d.month - 1
        elif kd == "yearly":
            k = d.year
        else:
            n, unit, frm = v
            if d <= frm:
                return 0
            if unit in ("day", "week"):
                step = n * (7 if unit == "week" else 1)
                return _ceil_div(d.toordinal() - frm.toordinal(), step)
            step = n * (12 if unit == "year" else 1)
            diff = (d.year * 12 + d.month) - (frm.year * 12 + frm.month)
            k = max(0, diff // step)
            while k > 0:
                prev = self._date(k - 1)
                if prev is None or prev < d:
                    break
                k -= 1
        # Step forward while the k-th date is before d (at most a couple of times).
        while True:
            x = self._date(k)
            if x is None or x >= d:
                return k
            k += 1

    def _iter(self, lo, hi=None, kmax=None):
        """Dates of the schedule from index lo on, up to date hi and index kmax."""
        k = lo
        while kmax is None or k <= kmax:
            x = self._date(k)
            if x is None or (hi is not None and x > hi):
                return
